// 1. Leer query params desde el Webhook
const query = $node["Webhook"].json.query || {};

const category = (query.category || "").toLowerCase().trim();
const search = (query.search || "").toLowerCase().trim();

// 2. Obtener productos desde la API
const products = $json.products || [];

// 3. Aplicar filtros
let filtered = products;

if (category) {
  filtered = filtered.filter(product =>
    (product.category || "").toLowerCase() === category
  );
}

if (search) {
  filtered = filtered.filter(product =>
    (product.title || "").toLowerCase().includes(search) ||
    (product.description || "").toLowerCase().includes(search)
  );
}

// 4. Transformar la data final
const transformed = filtered.map(product => ({
  /**
  title: product.title,
  price: product.price,
  rating: product.rating
  **/
  id: product.id,
  title: product.title,
  category: product.category,
  price: product.price,
  rating: product.rating,
  thumbnail: product.thumbnail
}));

// 5. Retornar respuesta estructurada
return [
  {
    json: {
      success: true,
      count: transformed.length,
      filters: {
        category: category || null,
        search: search || null
      },
      data: transformed
    }
  }
];
